  for (let y = 10; y < 18; y++) for (let x = 10; x < 18; x++) tiles[y * CHUNK_SIZE + x] = TILE_FLOOR;
  tiles[13 * CHUNK_SIZE + 9] = TILE_FLOOR; // one west entrance

